using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string inputStr;
    cin >> inputStr;
    string originalStr = inputStr;
    vector<char> chars(inputStr.begin(), inputStr.end());
    stack<char> s;
    for (char c : chars) {
        s.push(c);
    }
    vector<int> bracketsPositions;
    for (int i = 0; i < (int)chars.size(); i++) {
        if (chars[i] == '(' || chars[i] == ')') {
            s.pop();
            bracketsPositions.push_back(i);
        }
    }
    map<int, int> bracketPairs;
    for (size_t i = 0; i + 1 < bracketsPositions.size(); i += 2) {
        bracketPairs[bracketsPositions[i]] = bracketsPositions[i + 1];
    }
    vector<int> indicesToRemove;
    for (const auto& entry : bracketPairs) {
        int start = entry.first;
        int end = entry.second;
        for (int i = start; i <= end; i++) {
            indicesToRemove.push_back(i);
        }
    }
    vector<int> removeSet(indicesToRemove.begin(), indicesToRemove.end());
    sort(removeSet.begin(), removeSet.end());
    vector<int> filteredChars;
    for (int i = 0; i < (int)chars.size(); i++) {
        if (!binary_search(removeSet.begin(), removeSet.end(), i)) {
            filteredChars.push_back(chars[i]);
        }
    }
    vector<char> replacedChars;
    bool toggle = true;
    for (int i = 0; i < (int)chars.size(); i++) {
        if (binary_search(removeSet.begin(), removeSet.end(), i)) {
            if (chars[i] == '(' || chars[i] == ')' || chars[i] == '_') {
                if (toggle) {
                    replacedChars.push_back(' ');
                    toggle = false;
                }
            } else {
                replacedChars.push_back(chars[i]);
                toggle = true;
            }
        }
    }
    string resultStr(replacedChars.begin(), replacedChars.end());
    vector<int> lengthsAfter;
    {
        stringstream ss(resultStr);
        string part;
        while (ss >> part) {
            string trimmed = part;
            if (!trimmed.empty()) {
                lengthsAfter.push_back((int)trimmed.length());
            }
        }
    }
    vector<int> lengthsBefore;
    string replacedStr = regex_replace(inputStr, regex("\\(.*?\\) ?"), " ");
    replace(replacedStr.begin(), replacedStr.end(), '_', ' ');
    {
        stringstream ss(replacedStr);
        string part;
        while (ss >> part) {
            string trimmed = part;
            if (!trimmed.empty()) {
                lengthsBefore.push_back((int)trimmed.length());
            }
        }
    }
    sort(lengthsAfter.begin(), lengthsAfter.end());
    int maxLength = lengthsAfter.empty() ? 0 : lengthsAfter.back();
    cout << maxLength << " " << lengthsBefore.size() << "\n";
    return 0;
}

